pub(crate) fn native_modifier_to_string(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let flags = match args.first() {
        Some(Value::Int(v)) => *v,
        _ => 0,
    };
    let mut parts = Vec::new();
    if (flags & 0x0001) != 0 {
        parts.push("public");
    }
    if (flags & 0x0002) != 0 {
        parts.push("private");
    }
    if (flags & 0x0004) != 0 {
        parts.push("protected");
    }
    if (flags & 0x0008) != 0 {
        parts.push("static");
    }
    if (flags & 0x0010) != 0 {
        parts.push("final");
    }
    if (flags & 0x0020) != 0 {
        parts.push("synchronized");
    }
    if (flags & 0x0040) != 0 {
        parts.push("volatile");
    }
    if (flags & 0x0080) != 0 {
        parts.push("transient");
    }
    if (flags & 0x0100) != 0 {
        parts.push("native");
    }
    if (flags & 0x0200) != 0 {
        parts.push("interface");
    }
    if (flags & 0x0400) != 0 {
        parts.push("abstract");
    }
    if (flags & 0x0800) != 0 {
        parts.push("strictfp");
    }
    let s = parts.join(" ");
    Ok(Some(Value::Object(Some(ctx.create_string(&s)))))
}

pub(crate) fn native_modifier_class_modifiers(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    // PUBLIC | PROTECTED | PRIVATE | ABSTRACT | STATIC | FINAL | STRICT
    Ok(Some(Value::Int(
        0x0001 | 0x0004 | 0x0002 | 0x0400 | 0x0008 | 0x0010 | 0x0800,
    )))
}

